from collections import deque, Counter

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if col==0 or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); pts=[]
   while q:
    y,x=q.pop();pts.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col:
      seen.add((yy,xx));q.append((yy,xx))
   out.append((col,len(pts),min(y for y,x in pts),min(x for y,x in pts)))
 return sorted(out,key=lambda z:-z[1])
